concepts.code:
components:
  schemas:
    Book:
      type: object
      required: [id, title, isbn]
      additionalProperties: false
      properties:
        id: { type: string, format: uuid, readOnly: true }
        title: { type: string, minLength: 1, maxLength: 200 }
        isbn: { type: string, pattern: '^\d{13}$' }
        pages: { type: integer, minimum: 1 }
        price: { type: number, multipleOf: 0.01 }
        subtitle: { type: [string, 'null'] }   # 3.1 nullability
        genre: { type: string, enum: [fiction, science, history] }
        tags:
          type: array
          items: { type: string }
          uniqueItems: true
        publishedAt: { type: string, format: date-time }

# TypeScript types + a typed fetch client
npx openapi-typescript ./openapi.yaml -o ./src/api.d.ts

